sql.where:
r.game_type = 'nlld'

    AND r.game_id = #{q.gameId}


    AND r.instance_id = #{q.instanceId}


    AND r.school_id = #{q.schoolId}


    AND (r.department_id = #{q.departmentId}
         OR EXISTS (SELECT 1 FROM gkzh_school_department d
                    WHERE d.department_id = r.department_id
                      AND FIND_IN_SET(#{q.departmentId}, d.ancestors)))


    AND r.major LIKE CONCAT('%', #{q.major}, '%')


    AND r.student_no LIKE CONCAT('%', #{q.studentNo}, '%')


    AND r.gender IN ('男', '0')


    AND r.gender IN ('女', '1')


    AND (r.gender IS NULL OR TRIM(r.gender) = '' OR r.gender NOT IN ('男', '0', '女', '1'))


    AND r.result_type = #{q.resultType}


    AND (r.top1_dimension_id = (SELECT dd.dimension_id FROM gkzh_nlld_dimension dd
                                WHERE dd.dimension_code = #{q.dimensionCode})
         OR r.top2_dimension_id = (SELECT dd.dimension_id FROM gkzh_nlld_dimension dd
                                   WHERE dd.dimension_code = #{q.dimensionCode}))


    AND r.status = #{q.status}


    AND r.scan_time >= #{q.startDate}


    AND r.scan_time < #{q.endDate}

mapper.select:
SELECT r.* FROM gkzh_nlld_record r
WHERE r.game_type = 'nlld' AND r.game_id = #{gameId}
ORDER BY r.record_id DESC
LIMIT #{limit}
